// ============================================================
// SAFETY NET - Verificación de close_conversation
// ============================================================

const agentOutput = $input.first().json;
const outputText = agentOutput.output || '';
const steps = agentOutput.intermediateSteps || [];

// ============================================================
// CAPA 1: Regex de palabras clave de despedida
// ============================================================
const FAREWELL_KEYWORDS = /asesor|contactar[áa]|nos comunicamos|te vamos a contactar|un representante|en breve|a la brevedad|hasta luego|hasta pronto|fue un placer|cualquier consulta|no dudes en|chau|bye|suerte|\u3010alert:close_conversation\u3011/i;

const hasFarewellKeyword = FAREWELL_KEYWORDS.test(outputText);

// Si no hay keywords, pasar de largo
if (!hasFarewellKeyword) {
  return [{
    json: {
      action: 'passthrough',
      output: outputText,
      intermediateSteps: steps
    }
  }];
}

// ============================================================
// CAPA 2: ¿Se ejecutó close_conversation?
// ============================================================
const closeStep = steps.find(s =>
  s.action?.tool?.toLowerCase().startsWith('close_conversation')
);

const closeCalled = !!closeStep;

// Caso especial: tiene el alert tag pero no ejecutó la tool
// → recovery directo sin LLM
const hasAlertTag = outputText.includes('【alert:close_conversation】');

if (hasAlertTag && !closeCalled) {
  return [{
    json: {
      action: 'force_recovery',
      reason: 'alert_tag_sin_tool',
      output: outputText,
      intermediateSteps: steps
    }
  }];
}

// Keywords encontradas + tool ejecutada correctamente → ok
if (closeCalled) {
  return [{
    json: {
      action: 'passthrough',
      output: outputText,
      intermediateSteps: steps
    }
  }];
}

// Keywords encontradas + tool NO ejecutada → mandar al LLM verificador
return [{
  json: {
    action: 'needs_llm_verification',
    output: outputText,
    intermediateSteps: steps
  }
}];

